#include <limits>
#include <iostream>
#include <cmath>

int main() {
    using T = double;
    std::cout << "Radix: " << std::numeric_limits<T>::radix << "\n";
    std::cout << "Binary digits (mantissa): " << std::numeric_limits<T>::digits << "\n";
    std::cout << "Guaranteed decimal digits: " << std::numeric_limits<T>::digits10 << "\n";
    std::cout << "Epsilon: " << std::numeric_limits<T>::epsilon() << "\n";

    // Epsilon usage for comparison
    double x = 1.0;
    double y = 1.0 + std::numeric_limits<T>::epsilon() / 2.0; 
    if (x == y) { /* often true due to rounding */ }
}
